package com.javasmyths.highguard;
import java.util.*;
public class HighGuardRules {
 public static class Line {public String name,formula;public double tons,mcr,ep;Line(String n,double t,double c,double e,String f){name=n;tons=t;mcr=c;ep=e;formula=f;}}
 public static class BatteryResult {public String name,category;public int batteries,bearing,factor,mounts;public double tons,ep,mcr;}
 public static class Report {
  public boolean valid;public List<String> errors=new ArrayList<>(),notes=new ArrayList<>();public List<Line> lines=new ArrayList<>();public List<BatteryResult> batteries=new ArrayList<>();public Map<String,Integer> crewSections=new LinkedHashMap<>();
  public double used,cargo,fuel,jumpFuel,plantFuel,driveTons,totalMcr,price,architectFee,energy,energyUsed,energyRemaining,bearingPercent,spinalTons,disposableCost,dropJump,dropManeuver,dropPower,rooms,capacitorStorage;
  public int agility,crew,requiredRooms,requiredLow,armor,hardpoints,turrets,bays,launchPerTurn;public String usp="",size="";
  void add(String n,double t,double c,double e,String formula){lines.add(new Line(n,t,c,e,formula));used+=t;totalMcr+=c;energyUsed+=e;}
 }
 static void err(Report r,boolean bad,String message){if(bad)r.errors.add(message);}
 static boolean range(int n,int low,int high){return n>=low&&n<=high;}
 static boolean range(double n,double low,double high){return Double.isFinite(n)&&n>=low&&n<=high;}
 public static int computerMinimum(int hull){return hull>=1000000?7:hull>=100000?6:hull>=50000?5:hull>=10000?4:hull>=4000?3:hull>=1000?2:1;}
 public static double bearing(int hull){int i=Catalog.sizeIndex(hull);return i<20?1:i<=32?Math.max(.5,1-.05*(i-19)):.5;}
 public static Report calculate(Design d){Report r=new Report();
  err(r,d.name==null||d.name.trim().isEmpty()||d.name.length()>120,"Give the ship a name of 1–120 characters.");err(r,d.shipClass==null||d.shipClass.length()>120||d.purpose==null||d.purpose.length()>1000,"Class or purpose is too long.");err(r,d.type==null||!d.type.matches("[A-HJ-NP-Z]{2}"),"Use two High Guard type-code letters (no I or O).");
  err(r,!range(d.hull,100,1000000),"Hull must be 100–1,000,000 displacement tons. Small-craft construction is a separate rule set.");err(r,!range(d.tl,7,15),"Shipyard tech level must be 7–15.");err(r,!range(d.configuration,1,9),"Choose a hull configuration.");err(r,!range(d.jump,0,6)||!range(d.maneuver,0,6)||!range(d.power,1,50),"Jump and maneuver must be 0–6; power plant 1–50.");err(r,!range(d.armor,0,15)||!range(d.damper,0,9)||!range(d.meson,0,9)||!range(d.globe,0,4),"Armor or screen factor is out of range.");err(r,!range(d.auxBridges,0,10),"Auxiliary bridges must be 0–10.");
  err(r,!range(d.rooms,-1,1000000)||!range(d.lowBerths,0,2000000)||!range(d.emergencyBerths,0,1000000)||!range(d.passengers,0,1000000)||!range(d.lowPassengers,0,2000000)||!range(d.troops,0,1000000)||!range(d.extraCrew,0,1000000)||!range(d.launchTubes,0,1000),"Crew, quarters, passengers or launch facilities are out of range.");
  err(r,!range(d.fuel,-1,1000000)||!range(d.cargo,-1,1000000)||d.fuel<0&&d.fuel!=-1||d.cargo<0&&d.cargo!=-1,"Fuel/cargo must be automatic (-1) or nonnegative tons.");err(r,!range(d.extraCapacitors,0,1000000)||!range(d.otherTons,0,1000000)||!range(d.otherMcr,0,1e9)||!range(d.budget,0,1e9)||!range(d.dropTanks,0,1000000),"Additional allocations must be finite, nonnegative values within limits.");
  err(r,d.batteries==null||d.batteries.size()>40||d.craft==null||d.craft.size()>30,"Maximum 40 armament groups and 30 carried-craft groups.");err(r,!Arrays.asList("A","B").contains(d.starport),"Select class A or B shipyard.");if(!r.errors.isEmpty())return r;
  r.size=Catalog.sizeCode(d.hull);r.bearingPercent=bearing(d.hull);int[] mTl={0,7,7,8,8,8,9},jTl={0,9,11,12,13,14,15};
  err(r,d.jump>0&&d.starport.equals("B"),"Jump-capable ships require a class A shipyard.");err(r,d.tl<mTl[d.maneuver]||d.tl<jTl[d.jump],"The selected drives are above the shipyard's tech level.");err(r,d.power<Math.max(d.jump,d.maneuver),"Power plant number must equal or exceed jump and maneuver ratings.");err(r,d.jump==0&&d.maneuver==0,"A non-starship needs a maneuver drive.");err(r,d.armor>d.tl,"Added armor factor cannot exceed ship tech level.");err(r,d.configuration==7&&d.armor>0,"Dispersed structures cannot have hull armor.");
  double hullPrice=d.configuration>=8?d.hull*((d.configuration==8?.8:.65)*.001+.0001):d.hull*.1*Catalog.HULL_MULT[d.configuration];r.add("Hull · "+Catalog.CONFIG[d.configuration],0,hullPrice,0,d.configuration>=8?"Cr1,000/interior ton + Cr100/hull ton":"Hull tons × MCr0.1 × configuration modifier");
  if(d.configuration>=8)r.add("Planetoid structural allowance",d.hull*(d.configuration==8?.2:.35),0,0,d.configuration==8?"20% of hull":"35% of hull");
  double mt=d.maneuver==0?0:d.hull*(3*d.maneuver-1)*.01,jt=d.jump==0?0:d.hull*(d.jump+1)*.01,pt=d.hull*.01*d.power*(d.tl>=15?1:d.tl>=13?2:d.tl>=9?3:4);r.driveTons=mt+jt+pt;
  r.add("Maneuver drive · "+d.maneuver+"G",mt,mt*(d.maneuver==1?1.5:d.maneuver==2?.7:.5),0,"(3M − 1)% of hull; price by drive number");r.add("Jump drive · J"+d.jump,jt,jt*4,0,"(J + 1)% of hull; MCr4/drive ton (zero when omitted)");r.add("Power plant · P"+d.power,pt,pt*3,0,"TL multiplier × P% of hull; MCr3/drive ton");
  r.energy=d.hull*.01*d.power;r.jumpFuel=d.hull*.1*d.jump;r.plantFuel=r.energy;r.fuel=d.fuel==-1?r.jumpFuel+r.plantFuel:d.fuel;err(r,r.fuel+d.dropTanks+1e-7<r.jumpFuel+r.plantFuel,"Fuel plus drop tanks is below one full jump and four weeks of plant fuel.");err(r,r.fuel+1e-7<r.plantFuel,"Internal fuel must cover four weeks of power-plant operation.");r.add("Internal fuel",r.fuel,0,0,"10% hull × jump + 1% hull × plant; drop tanks may supply jump fuel");
  if(d.dropTanks>0){r.disposableCost=.01+.001*d.dropTanks;r.add("External disposable tanks",0,r.disposableCost,0,"Cr10,000 + Cr1,000/fuel ton; no internal tonnage");double ratio=d.hull/(d.hull+d.dropTanks);r.dropJump=d.jump==0?0:Math.max(0,Math.floor((d.jump+1)*ratio-1+1e-9));r.dropManeuver=d.maneuver==0?0:Math.max(0,Math.floor(((3*d.maneuver-1)*ratio+1)/3+1e-9));r.dropPower=d.power*ratio;r.notes.add("With drop tanks retained: J"+(int)r.dropJump+", "+(int)r.dropManeuver+"G; rated performance returns after jettison. Replace tanks after use.");}
  if(d.scoops){err(r,d.configuration>6,"This hull cannot skim fuel; use a separate tanker.");r.add("Fuel scoops",0,.001*d.hull,0,"Cr1,000/hull ton");}
  if(d.purifier){err(r,d.tl<8,"Fuel purification plants require TL8+.");int index=Math.max(0,d.tl-8);double multiplier=Math.max(.2,r.fuel/1000);double[] t={50,45,40,35,30,25,20,15},p={.2,.19,.18,.17,.16,.15,.14,.15};r.add("Fuel purification plant",t[index]*multiplier,p[index]*multiplier,0,"TL table × max(0.2, internal fuel / 1,000)");}else if(d.scoops)r.notes.add("Scooped fuel remains unrefined; arrange external purification before use.");
  r.add("Main bridge",Math.max(20,d.hull*.02),d.hull*.005,0,"2% hull, minimum 20t; Cr5,000/hull ton");if(d.auxBridges>0)r.add("Auxiliary bridges × "+d.auxBridges,Math.max(20,d.hull*.02)*d.auxBridges,d.hull*.005*d.auxBridges,0,"Same space and cost as the main bridge");
  Catalog.Computer computer=Catalog.COMPUTERS.get(d.computer);err(r,computer==null,"Select a computer model.");if(computer!=null){err(r,computer.tl>d.tl,"Computer is above the shipyard tech level.");err(r,computer.model<computerMinimum(d.hull),"Hull size requires at least Model/"+computerMinimum(d.hull)+".");err(r,computer.model+(d.computer.endsWith("bis")?1:0)<d.jump,"Computer cannot control the selected jump rating.");r.add("Computer · Model/"+d.computer,computer.tons,computer.mcr,computer.ep,"Published computer table");}
  r.armor=d.armor+(d.configuration==8?3:d.configuration==9?6:0);if(d.armor>0){double t=d.hull*.01*(d.tl>=14?1:d.tl>=12?2:d.tl>=10?3:4)*(1+d.armor);r.add("Additional hull armor · "+d.armor,t,t*(.3+.1*d.armor),0,"TL armor multiplier × (1 + added factor)% of hull");}
  Set<String> weaponTypes=new HashSet<>();Map<String,Integer> factors=new HashMap<>();Map<String,String> categoryMount=new HashMap<>();Catalog.Major major=Catalog.MAJORS.get(d.spinal);err(r,!"None".equals(d.spinal)&&major==null,"Choose a valid spinal mount.");int gunnery=0;
  if(major!=null){err(r,major.tl>d.tl,"Spinal mount exceeds ship tech level.");r.spinalTons=major.tons;r.add("Spinal mount · "+major.id,major.tons,major.mcr,major.ep,"Published major-weapon table; one per ship");gunnery+=(int)Math.ceil(major.tons/100);weaponTypes.add(major.category);factors.put(major.category,Catalog.CODES.indexOf(d.spinal.charAt(d.spinal.length()-1)));}
  for(Design.Battery b:d.batteries){if(b==null){r.errors.add("Invalid armament group.");continue;}Catalog.Weapon w=Catalog.WEAPONS.get(b.weapon);err(r,w==null||!range(b.mounts,0,10000)||!range(b.weaponsPerMount,1,3)||!range(b.mountsPerBattery,1,10),"Invalid weapon group: choose a catalogue item and bounded whole counts.");if(w==null||b.mounts<=0||!range(b.mounts,0,10000)||!range(b.weaponsPerMount,1,3)||!range(b.mountsPerBattery,1,10))continue;
   err(r,w.tl>d.tl,"Unavailable at TL"+d.tl+": "+w.name);err(r,b.weaponsPerMount>w.maxPerMount,"Too many weapons per mount for "+w.name);err(r,w.bay&&(b.weaponsPerMount!=1||b.mountsPerBattery!=1),"Each bay has one weapon and forms its own battery.");err(r,b.mounts%b.mountsPerBattery!=0,"Mount count must divide evenly into batteries: "+w.name);err(r,major!=null&&major.category.equals(w.category),"A spinal weapon excludes secondary weapons of that type.");
   int f=w.category.equals("Empty")?0:w.factor(b.weaponsPerMount*b.mountsPerBattery,d.tl);String signature=w.bay?b.weapon:"turret";if(!w.category.equals("Empty")){String old=categoryMount.putIfAbsent(w.category,signature);err(r,old!=null&&!old.equals(signature),"Use identical bays or turret weapons for "+w.category+", not both.");Integer oldFactor=factors.putIfAbsent(w.category,f);err(r,oldFactor!=null&&oldFactor!=f,"All batteries of "+w.category+" must share one USP factor.");weaponTypes.add(w.category);}
   BatteryResult br=new BatteryResult();br.name=w.name;br.category=w.category;br.mounts=b.mounts;br.batteries=b.mounts/b.mountsPerBattery;br.bearing=Math.max(1,(int)Math.round(br.batteries*r.bearingPercent));br.factor=f;br.tons=b.mounts*w.tons;br.ep=b.mounts*b.weaponsPerMount*w.ep;br.mcr=b.mounts*(b.weaponsPerMount*w.mcr+(w.bay?w.tons*.01:0));r.batteries.add(br);r.add(w.name+" · "+br.batteries+" batteries",br.tons,br.mcr,br.ep,w.bay?"Bay shell + weapon; one battery per bay":b.weaponsPerMount+" weapons/mount × "+b.mountsPerBattery+" mounts/battery");if(w.bay){r.bays+=b.mounts;if(!w.category.equals("Empty"))gunnery+=2*b.mounts;}else{r.turrets+=b.mounts;gunnery+=br.batteries;}
  }
  Map<String,BatteryResult> grouped=new LinkedHashMap<>();for(BatteryResult b:r.batteries){BatteryResult first=grouped.get(b.category);if(first==null)grouped.put(b.category,b);else{first.name=b.category+" batteries (combined groups)";first.batteries+=b.batteries;first.mounts+=b.mounts;first.tons+=b.tons;first.ep+=b.ep;first.mcr+=b.mcr;}}r.batteries=new ArrayList<>(grouped.values());for(BatteryResult b:r.batteries)b.bearing=b.category.equals("Empty")?0:Math.max(1,(int)Math.round(b.batteries*r.bearingPercent));
  r.hardpoints=Math.max(0,(int)Math.floor((d.hull-r.spinalTons-r.bays*1000)/100));err(r,r.spinalTons+1000*r.bays+100*r.turrets>d.hull+1e-7,"Weapon allocation exceeded: each bay reserves 1,000 hull tons, each turret 100, in addition to the spinal mount.");
  int screenCount=0;for(int i=0;i<2;i++){int f=i==0?d.damper:d.meson;if(f>0){screenCount++;err(r,Catalog.SCREEN_TL[f]>d.tl,"Selected "+(i==0?"damper":"meson screen")+" exceeds tech level.");r.add(i==0?"Nuclear damper · "+f:"Meson screen · "+f,i==0?Catalog.DAMP_TONS[f]:Catalog.MESON_TONS[f],i==0?Catalog.DAMP_COST[f]:Catalog.MESON_COST[f],i==0?10*f:.002*f*d.hull,"Published screen table");}}
  if(d.globe>0){screenCount++;err(r,d.tl<15||!d.artifactPermission,"Black globes require TL15 and explicit referee/artifact permission.");r.add("Black globe · "+d.globe,new double[]{0,10,15,20,25}[d.globe],400*d.globe,0,"Experimental/artifact equipment; not a commercial purchase");}
  r.capacitorStorage=(d.hull*.005*d.jump+d.extraCapacitors)*36;if(d.extraCapacitors>0)r.add("Extra capacitors",d.extraCapacitors,4*d.extraCapacitors,0,"MCr4/ton; 36 EP storage/ton (jump capacitors included separately)");
  if(weaponTypes.size()>0||screenCount>0)gunnery+=1+weaponTypes.size()+4*screenCount;
  int craftCount=0,vehicleCount=0,flight=0;double largest=0;for(Design.Craft c:d.craft){if(c==null){r.errors.add("Invalid craft group.");continue;}err(r,c.name==null||c.name.length()>100||!range(c.quantity,0,10000)||!range(c.tons,1,1000000)||!range(c.mcr,0,1e9)||!range(c.crew,1,1000),"Carried craft needs a name, finite size/cost and bounded counts.");if(c.quantity<=0||!range(c.quantity,0,10000)||!range(c.tons,1,1000000)||!range(c.mcr,0,1e9)||!range(c.crew,1,1000))continue;boolean vehicle="vehicle".equals(c.kind); err(r,!vehicle&&!"craft".equals(c.kind),"Choose carried craft or surface equipment."); double space=c.tons*(vehicle||d.configuration==7?1:c.tons>=100?1.1:d.hull>1000?1.3:1);r.add("Carried · "+c.name+" × "+c.quantity,space*c.quantity,(c.mcr+(vehicle||d.configuration==7?0:space*.002))*c.quantity,0,"Craft purchase + Cr2,000/allocated ton; small craft ×1.3 over 1,000t, big craft ×1.1");if(vehicle){vehicleCount+=c.quantity;}else{craftCount+=c.quantity;flight+=c.quantity*(c.crew+1);largest=Math.max(largest,c.tons);}}
  if(craftCount>0)flight++;if(vehicleCount>3)flight+=(int)Math.ceil(vehicleCount/3.0);if(d.launchTubes>0){err(r,craftCount==0,"Launch tubes require carried craft.");r.add("Launch tubes × "+d.launchTubes,25*largest*d.launchTubes,.002*25*largest*d.launchTubes,0,"25 × largest craft tons per tube; Cr2,000/ton");flight+=10*d.launchTubes;}
  r.launchPerTurn=d.configuration==7?craftCount:Math.max(1,(int)Math.floor(d.hull/10000));if(d.launchTubes>0)r.notes.add("Each rapid-launch tube may deploy its squadron in accordance with the combat rules; ordinary launch rate shown excludes tubes.");
  if(d.hull<=1000){r.crewSections.put("Pilot",1);if(d.hull>200)r.crewSections.put("Navigator",1);if(r.driveTons>=10)r.crewSections.put("Engineers",Math.max(1,(int)Math.floor(r.driveTons/35)));r.crewSections.put("Gunners",r.turrets);if(d.hull>=200||d.passengers>0)r.crewSections.put("Medical",Math.max(1,(int)Math.ceil(d.passengers/120.0)));if(d.passengers>0)r.crewSections.put("Stewards",(int)Math.ceil(d.passengers/8.0));if(flight>0)r.crewSections.put("Flight",flight);r.notes.add("Ships of 1,000t or less use Book 1/2 crew rules; this worksheet assumes separate qualified roles.");}
  else{r.crewSections.put("Command",d.hull>20000?Math.max(11,(int)Math.ceil(d.hull*5/10000.0)):11);r.crewSections.put("Engineering",Math.max(1,(int)Math.ceil(r.driveTons/100)));r.crewSections.put("Gunnery",gunnery);r.crewSections.put("Flight",flight);r.crewSections.put("Service",(int)Math.ceil(d.hull*(d.troops>0?2:3)/1000.0));}
  if(d.extraCrew>0)r.crewSections.put("Additional assigned crew",d.extraCrew);r.crew=r.crewSections.values().stream().mapToInt(x->x).sum();int individual=1;if(d.hull>1000){individual=0;for(int n:r.crewSections.values())if(n>0)individual++;if(d.troops>0)individual++;}
  r.requiredRooms=d.military?(int)Math.ceil((r.crew+d.troops+individual)/2.0)+d.passengers:r.crew+d.troops+d.passengers;r.rooms=d.rooms==-1?r.requiredRooms:d.rooms;err(r,r.rooms<r.requiredRooms,"Insufficient staterooms: need "+r.requiredRooms+" for assigned crew, troops and passengers.");r.add("Staterooms",r.rooms*4,r.rooms*.5,0,"4t / MCr0.5 each; military sharing, officers assigned individual rooms");
  r.requiredLow=d.lowPassengers+(d.frozenWatch?(int)Math.ceil((r.crew+d.troops)*.5):0);err(r,d.lowBerths<r.requiredLow,"Insufficient low berths: need "+r.requiredLow+" including passengers/frozen watch.");r.add("Low berths",d.lowBerths*.5,d.lowBerths*.05,0,"0.5t / Cr50,000 each");if(d.emergencyBerths>0)r.add("Emergency low berths",d.emergencyBerths,.1*d.emergencyBerths,0,"1t / Cr100,000 each; four places, not frozen-watch berths");
  if(d.otherTons>0||d.otherMcr>0)r.add("Other mission fittings",d.otherTons,d.otherMcr,0,"Explicit referee allocation; no assumed combat effect");r.cargo=d.cargo==-1?Math.max(0,d.hull-r.used):d.cargo;r.add("Cargo hold",r.cargo,0,0,d.cargo==-1?"Remaining interior space":"Explicit cargo allocation");err(r,r.used>d.hull+1e-6,"Hull over capacity by "+fmt(r.used-d.hull)+" tons.");err(r,r.energyUsed>r.energy+1e-6,"Equipment requires "+fmt(r.energyUsed)+" EP; plant supplies "+fmt(r.energy)+". Increase the power plant.");r.energyRemaining=r.energy-r.energyUsed;r.agility=Math.max(0,Math.min(d.maneuver,(int)Math.floor(r.energyRemaining/(.01*d.hull)+1e-9)));r.price=r.totalMcr*(d.repeatClass?.8:1);r.architectFee=d.navalArchitect?r.price*.01:0;err(r,d.budget>0&&r.price+r.architectFee>d.budget,"Ship plus architect fee exceeds the budget.");
  if(d.repeatClass)r.notes.add("20% class discount assumes an identical follow-on vessel, not the first design in a new class.");if(d.power>=Catalog.CODES.length())r.notes.add("Plant numbers above 33 use bracketed decimal notation in this worksheet's profile; the printed USP uses single-character factors.");if(d.importNotes!=null&&!d.importNotes.isEmpty()&&!d.importReviewed)r.errors.add("Review and acknowledge the Book 2 conversion notes before saving.");
  int crewCode=r.crew==0?0:(int)Math.floor(Math.log10(r.crew))+1;r.usp=d.type+"-"+r.size+d.configuration+Catalog.code(d.jump)+Catalog.code(d.maneuver)+Catalog.code(d.power)+(computer==null?"?":computer.usp)+Catalog.code(crewCode)+"-"+Catalog.code(r.armor)+Catalog.code(factors.getOrDefault("Sand",0))+Catalog.code(d.meson)+Catalog.code(d.damper)+Catalog.code(d.globe)+Catalog.code(factors.getOrDefault("Repulsor",0))+"-"+Catalog.code(factors.getOrDefault("Laser",0))+Catalog.code(factors.getOrDefault("Energy",0))+Catalog.code(factors.getOrDefault("Particle",0))+Catalog.code(factors.getOrDefault("Meson",0))+Catalog.code(factors.getOrDefault("Missile",0))+"-0";
  r.valid=r.errors.isEmpty();return r;
 }
 public static String fmt(double x){return String.format(java.util.Locale.ROOT,"%,.2f",x);}
}
